   cloze('أكمل التجربة الأولى', 'صفّ ___ تذكّر ستّة وأربعين في المئة، وصفّ ___ ثمانية وستّين، لكنّ الصفّين لم يُقسما بـ___.', ['القائمة', 'القصّة', 'القرعة'], ['المساء', 'الصباح', 'الاختبار']),
   cloze('أكمل الخلاصة', 'اثنا عشر ألف ريال، ثمانية ___، أربعة ___، قياس بعد شهر وبعد ثلاثة أشهر في المفردات و___ معًا.', ['صفوف', 'أشهر', 'القواعد'], ['معلّمين', 'سنوات', 'الحضور']),
   tf('سيختبر الطلّاب معلّم غير ماريا.', 'ماريا: يُقسمون بالقرعة لا باختياري، ويختبرهم معلّم غيري لا أنا.', 'true', 'من تغييرات الطلب بعد الاعتراض الأوّل.'),
   tf('قالت ماريا إنّ استبانة الطلّاب تثبت أنّ القصّة أفضل.', 'ماريا: وهذا ليس دليلًا على أنّ القصّة أفضل، بل دليل على أنّ الطلّاب يظنّون ذلك.', 'false', 'فرّقت بين ما يثبت وما يُظنّ.'),
   tf('وافقت اللجنة على المنحة.', 'الطلب على مكتب سلمى، واللجنة ثلاثة: سلمى وهند وعمر.', 'ng', 'لم يُذكر قرار اللجنة في النصّ.'),
   tap('المس كلمة الحدّ في الادّعاء', ['ادّعائي', 'الذي', 'أطلب', 'المنحة', 'لاختباره', 'لا', 'لإثباته'], 'لاختباره'),
   tap('المس كلمة التسليم الكامل', ['وأسلّم', 'بهذا', 'الاعتراض', 'كاملًا', 'ولا', 'أجد', 'ما', 'أردّ', 'به'], 'كاملًا'),
   tap('المس رابط الإجراء الجديد', ['ولذلك', 'أضيف', 'إلى', 'طلبي', 'ما', 'لم', 'يكن', 'فيه'], 'ولذلك'),
   dic('المنحة لاختبار لا لإثبات.', ['المنحة لاختبار لا لإثبات']),
