   cloze('أكمل حساب الانسحاب', 'انسحب في العام الماضي ___ عشر في المئة، فيبقى مئة وستّة و___، والحدّ الأدنى مئة و___.', ['خمسة', 'ثلاثون', 'عشرون'], ['سبعة', 'أربعون', 'ستّون']),
