   tf('اعتذرت هند قبل اعتراضها لأنّها هي التي علّمت ماريا أن تتوقّع.', 'هند: سؤالي لم يكن في الجزء الثاني من طلبكِ، وأعتذر لأنّي أنا التي علّمتكِ أن تتوقّعي.', 'true', 'الاعتراض من المعلّمة نفسها.'),
   tf('زادت الميزانية بعد القياس الثالث.', 'ماريا: وآخذها من بند الطباعة، وتبقى الميزانية اثني عشر ألفًا لا تزيد ريالًا.', 'false', 'نُقلت من بند إلى بند.'),
